insert into public.publication_posts
  (publication, slug, n, hook, narration, beats, caption, published, date, ts, taxon, still, wide, gallery, clip_id, permalink, platform, updated_at) values
  ('softmoneyjournal', 'i-let-the-cup-go-cold', 1, 'i let the cup go cold', '["i let the cup go cold on purpose.","i sit down with the notebook, check the balance, move one thing where it belongs.","by the time i''m done the tea has gone lukewarm, and that''s the whole reset.","then i close the book and go make a fresh one."]'::jsonb, '["the money part takes less time than the tea","i check, i move one thing, i close it","cold tea means i didn''t spiral"]'::jsonb, 'the tea goes cold and i''m already done', true, '2026-09-14T01:20:57.411Z', 1789348857411, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p59.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p59-w.jpg', '[]'::jsonb, 'smgen-1788484391267-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-pay-the-envelopes-in-order', 3, 'i pay the envelopes in order', '["i pay the envelopes in order.","the order is decided before the cash ever leaves the bank, the same sequence every payday.","bills envelope first, then the one i never touch, then groceries — same order every payday.","whatever is left in my hands after that is allowed to be fun money."]'::jsonb, '["the order is decided before the cash ever leaves the bank","each envelope gets filled in the same order every time","whatever is left over is mine to spend without guilt"]'::jsonb, 'same order every payday and the guilt never shows up', true, '2026-09-12T00:39:56.464Z', 1789173596464, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p57.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p57-w.jpg', '[]'::jsonb, 'smgen-1788312380158-0', 'https://www.tiktok.com/@softmoneyjournal/video/7400000000000000101', 'tiktok', '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-count-it-into-envelopes', 4, 'i count it into envelopes', '["i count it into envelopes.","one trip, one afternoon, and the money stops being a number i''m scared of.","each envelope already has a job, so i''m not deciding anything while i''m tired.","whatever''s still in my hand at the end is honestly mine to spend."]'::jsonb, '["cash comes out of the account in one trip","every envelope gets its job before anything gets spent","what''s left in my hand is honestly mine"]'::jsonb, 'the counting is the calm part', true, '2026-09-11T00:43:47.120Z', 1789087427120, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p56.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p56-w.jpg', '[]'::jsonb, 'smgen-1788286658349-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-date-every-page', 5, 'i date every page', '["i date every page.","before i write a single number, the date goes at the top — so the money has a day attached to it, not a vague feeling.","then i write down what i actually spent, in my own handwriting, slowly enough to notice it.","the page is finished when the pen stops. i close the notebook and i don''t reopen the thought until tomorrow."]'::jsonb, '["the date goes at the top before anything else","then whatever i spent, in my own handwriting","the page is done when the pen stops"]'::jsonb, 'the date first, then the numbers, then i close it', true, '2026-09-10T00:39:32.781Z', 1789000772781, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p55.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p55-w.jpg', '[]'::jsonb, 'smgen-1788139029336-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-write-the-same-three-lines', 6, 'i write the same three lines', '["i write the same three lines every week.","what came in. what has to go out. what''s left after that.","it takes about four minutes and the page looks the same every time.","then the pen goes down, and money stops being something i carry around."]'::jsonb, '["every sunday, same three lines in the same notebook","what came in, what has to go out, what''s left","then the pen goes down and i''m done thinking about it"]'::jsonb, 'same three lines, same page, every sunday', true, '2026-09-09T00:21:09.538Z', 1788913269538, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p54.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p54-w.jpg', '[]'::jsonb, 'smgen-1788054658393-0', 'https://www.instagram.com/reel/Cxxfixture02/', 'instagram', '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-pen-decides-before-i-do', 7, 'i moved one thing and closed the book', '["i moved one thing and closed the book.","that was the whole of it."]'::jsonb, '["money moves in a fixed order","the page is written first","wanting comes last, and calmly"]'::jsonb, 'the order goes on the page before payday touches anything', true, '2026-09-08T00:24:01.628Z', 1788827041628, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p53.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p53-w.jpg', '[]'::jsonb, 'smgen-1787966987514-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'one-drawer-holds-the-money', 8, 'one drawer holds the money', '["one drawer holds the money.","every envelope, every note about it, lives in that one place.","on sunday i take it all out onto the desk and look at it for ten quiet minutes.","then it goes back in the drawer, and i stop carrying it around all week."]'::jsonb, '["everything money-related lives in one drawer","sunday i take it out onto the desk","it goes back in and i''m done"]'::jsonb, 'the drawer closes and so does the thinking', true, '2026-09-07T00:26:24.453Z', 1788740784453, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p52.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p52-w.jpg', '[]'::jsonb, 'smgen-1787880538560-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-wipe-the-desk-down', 9, 'i wipe the desk down', '["i wipe the desk down.","before a single app opens, the wood gets wiped and the mug gets moved to the corner.","a clear surface is the only permission slip i need to look at my money without my chest going tight.","then it''s ten quiet minutes, and the rest of the day belongs to me."]'::jsonb, '["the cloth goes over the wood before anything opens","a clean surface is the whole permission slip","then the money part takes ten quiet minutes"]'::jsonb, 'the desk gets wiped before the money gets looked at', true, '2026-09-06T00:27:23.745Z', 1788654443745, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p51.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p51-w.jpg', '[]'::jsonb, 'smgen-1787798822802-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-notebook-stays-open-here', 10, 'the notebook stays open here', '["the notebook stays open here.","i don''t put it away between sessions — it lives on the desk, spine flat, one page for the week.","every time money moves, i walk over and add a line. it takes eight seconds.","by sunday the page has already done the reset for me. nothing to catch up on."]'::jsonb, '["the desk is quiet and already clear","the notebook stays open all week","i add one line whenever i spend"]'::jsonb, 'leaving it open turned out to be the whole system', true, '2026-09-05T00:07:53.832Z', 1788566873832, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p50.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p50-w.jpg', '[]'::jsonb, 'smgen-1787711023302-0', 'https://www.youtube.com/shorts/smjFixture03', 'youtube', '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-pen-goes-back-down', 11, 'the pen goes back down', '["the pen goes back down.","i give the money ten quiet minutes on this page, and when the ten minutes are up, the pen goes back down.","i used to leave it open all evening, checking and re-checking, like watching a pot.","now the closed planner means it''s handled, and i am allowed to think about something else."]'::jsonb, '["the ritual ends on purpose, not when i run out of worry","closing the planner is the signal that money time is over","the calm comes from the ending, not the checking"]'::jsonb, 'the pen going back down is the whole ritual', true, '2026-09-04T00:09:28.502Z', 1788480568502, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p49.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p49-w.jpg', '[]'::jsonb, 'smgen-1787625191053-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-fill-the-page-before-payday', 12, 'i fill the page before payday', '["i fill the page before payday.","the day before, i sit here and write the week out — bills on their lines, savings on its line, one line left for something i want.","nothing has landed yet, so nothing feels spent. i''m just writing.","then payday comes and i don''t decide anything. i follow the page."]'::jsonb, '["the planner is open a day early, pen resting on it","every line written while nothing has landed yet","when the money arrives the page is already decided"]'::jsonb, 'the page gets written the day before, so payday is just following it.', true, '2026-09-03T00:09:05.469Z', 1788394145469, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p48.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p48-w.jpg', '[]'::jsonb, 'smgen-1787534237357-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'payday-starts-at-this-desk', 13, 'payday starts at this desk', '["payday starts at this desk, not in my cart.","i sit down with the coffee before i touch anything — bills first, so the scary part is over while it''s still warm.","then the savings line, small and boring, moved before i can talk myself out of it.","whatever''s left after that is allowed to be fun. by the time the cup is empty, the money already knows where it''s going."]'::jsonb, '["payday morning, coffee down, nothing spent yet","bills first, savings second, then the wanting","the cup empties, the order is already done"]'::jsonb, 'payday runs in the same order every time, and the coffee is part of it', true, '2026-09-02T00:26:39.495Z', 1788308799495, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p47.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p47-w.jpg', '[]'::jsonb, 'smgen-1787447770209-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-ink-has-to-dry', 14, 'the ink has to dry', '["the ink has to dry.","i write the month out by hand at this desk, one line per bill, slow enough that the pen has to keep up with me.","by the time the last line dries i already know what''s real, and nothing on the page can surprise me later.","then the notebook closes, and money is done being the loudest thing in my head."]'::jsonb, '["one page, one pen, no phone in the frame","every bill written out longhand before i touch anything","i close the notebook and let the day go on"]'::jsonb, 'writing it out by hand made it feel handled', true, '2026-09-01T00:35:44.488Z', 1788222944488, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p46.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p46-w.jpg', '[]'::jsonb, 'smgen-1787360549147-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-sit-in-the-good-light', 15, 'i sit in the good light', '["i sit in the good light.","the desk gets the brightest hour, so that''s when i look at my money.","notebook open, pen down, nothing else on the table to distract me.","ten minutes in that light, then i close the page and don''t reopen it till next week."]'::jsonb, '["the desk gets the brightest hour of the morning","one notebook, one pen, nothing else on the surface","ten minutes, then the page closes and i''m done"]'::jsonb, 'the light does half the work', true, '2026-08-31T00:19:06.357Z', 1788135546357, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p45.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p45-w.jpg', '[]'::jsonb, 'smgen-1787274763128-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-write-the-number-down', 16, 'i write the number down', '["i write the number down.","checking my balance on my phone happens in a second and rattles me for an hour.","writing it by hand takes long enough that i stop bracing and just look at it.","once it''s on the page, it''s a fact i wrote, not a thing i''m avoiding."]'::jsonb, '["the number stops being scary once it''s ink","writing is slower than checking, on purpose","the page holds it so i don''t have to"]'::jsonb, 'the number is easier once it''s in my handwriting', true, '2026-08-30T00:19:50.295Z', 1788049190295, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p44.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p44-w.jpg', '[]'::jsonb, 'smgen-1787189293968-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-sit-down-before-i-decide', 17, 'i sit down before i decide', '["i sit down before i decide.","nothing gets moved while i''m standing up in the kitchen.","i sit, i look at the one page, and i move things in the order i already wrote down.","by the time the light shifts across the table, money is handled and i''m not thinking about it."]'::jsonb, '["the chair before the choice","one look, then the pen","the morning holds the whole thing"]'::jsonb, 'the chair is the whole ritual', true, '2026-08-29T00:28:22.104Z', 1787963302104, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p43.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p43-w.jpg', '[]'::jsonb, 'smgen-1787115639540-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'this-room-holds-my-reset', 18, 'this room holds my reset', '["This room holds my reset.","I check what came in and what went out.","I choose what needs my attention next.","Then I leave money here until next week."]'::jsonb, '["i check what came in and what went out","i choose what needs my attention next","then i leave money here until next week"]'::jsonb, 'a quiet room for a quieter money week', true, '2026-08-28T00:18:46.220Z', 1787876326220, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p42.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p42-w.jpg', '[]'::jsonb, 'smgen-1787061199614-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-split-it-before-i-spend', 19, 'i split it before i spend', '["i split it before i spend","the money comes out once, and then it gets sorted at this table — bills first, so the scary part is already handled","then the slow envelope, the one i don''t touch, counted out the same way every time","whatever is still in my hands after that is allowed to be spent, and i don''t argue with it"]'::jsonb, '["cash comes out in one trip","each envelope gets filled in order","what''s left is mine, guilt-free"]'::jsonb, 'the sorting is the whole ritual', true, '2026-08-27T00:28:42.269Z', 1787790522269, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p41.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p41-w.jpg', '[]'::jsonb, 'smgen-1786928633222-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-open-the-curtain-first', 20, 'i open the curtain first', '["i open the curtain first","the light hits the desk before i look at a single number","then the notebook, then the cup, then i start","ten quiet minutes in the window light, and money is handled for the week"]'::jsonb, '["light on the desk before anything else","the notebook and the cup, in that order","ten quiet minutes, then i close it"]'::jsonb, 'the light comes before the numbers', true, '2026-08-26T01:22:31.494Z', 1787707351494, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p40.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p40-w.jpg', '[]'::jsonb, 'smgen-1786888766713-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-planner-tells-me-the-order', 21, 'the planner tells me the order', '["the planner tells me the order.","i write three lines on the page before i move a single thing.","bills at the top, then the quiet line i keep for myself.","then whatever i want, last — and it doesn''t feel like a fight."]'::jsonb, '["pen down, page open, three lines","bills first, then the quiet line","then the wanting, on purpose"]'::jsonb, 'the page decides so i don''t have to', true, '2026-08-25T00:42:47.336Z', 1787618567336, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p39.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p39-w.jpg', '[]'::jsonb, 'smgen-1786841525068-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-tea-goes-down-first', 22, 'the tea goes down first', '["the tea goes down first, then i start.","bills get their turn before anything else. then the savings line. then, only then, the wanting.","i keep the order because it means i never have to argue with myself at the desk.","by the time the cup is empty, it''s handled. i put the pen down and go be a person."]'::jsonb, '["set the cup down, open the page","bills, then savings, then wants","close it while the tea is warm"]'::jsonb, 'the order is the whole trick — it decides for me so i don''t have to', true, '2026-08-24T00:14:18.520Z', 1787530458520, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p38.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p38-w.jpg', '[]'::jsonb, 'smgen-1786757768527-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-leave-the-pen-on-friday', 23, 'i leave the pen on friday', '["i leave the pen on the page on friday.","it sits across the open week, so nothing gets closed or put away.","when i come back, the page is already open and the pen is already there.","the setup is done, so the sitting down is easy."]'::jsonb, '["friday: pen goes across the open page","the page waits all weekend","sunday: it''s already started"]'::jsonb, 'the pen never goes back in the drawer', true, '2026-08-23T00:19:14.294Z', 1787444354294, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p37.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p37-w.jpg', '[]'::jsonb, 'smgen-1786602709550-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-table-is-clear-now', 25, 'the table is clear now', '["the table is clear now","this same table used to be a pile of envelopes i walked past for weeks","now it holds a cup, a pen, and one page with the week written on it","i didn''t get more disciplined. i just made the place i do this feel gentle enough to come back to"]'::jsonb, '["the same table used to be covered in mail i wouldn''t open","now it holds one cup and one open notebook","the change wasn''t discipline, it was making the table a calm place to sit"]'::jsonb, 'this table used to be a pile of envelopes i walked past for weeks', true, '2026-08-21T00:16:50.020Z', 1787271410020, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p35.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p35-w.jpg', '[]'::jsonb, 'smgen-1786423096576-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-clear-the-desk-first', 26, 'i clear the desk first', '["i clear the desk first.","everything goes except the notebook, the pen, and the coffee.","then i sit down, and the numbers are just numbers on a page.","the woman who wipes the desk down first is not the woman who used to avoid it."]'::jsonb, '["clearing the desk is the first money move","the notebook and pen stay, nothing else","by the time i sit down i''m already calm"]'::jsonb, 'the desk gets cleared before the numbers do', true, '2026-08-20T00:05:46.836Z', 1787184346836, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p34.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p34-w.jpg', '[]'::jsonb, 'smgen-1786340922953-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-keep-one-page-open', 27, 'i keep one page open', '["i keep one page open","the planner sits open on the desk all week, pen across it, so nothing has to be remembered","anything money touches goes on that page the moment it happens, one line, no tidying","on sunday i read the page once from the top, and then i close it and the week is done"]'::jsonb, '["the planner stays open on the desk all week, not filed away","every money thing gets written on that one page as it happens","sunday i read the page once, then close it"]'::jsonb, 'one page, open all week, closed on sunday', true, '2026-08-19T01:58:28.441Z', 1787104708441, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p33.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p33-w.jpg', '[]'::jsonb, 'smgen-1786259504050-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-desk-stopped-meaning-dread', 28, 'the desk stopped meaning dread', '["the desk stopped meaning dread","for a long time this was where i found out things i didn''t want to know","now it''s a notebook, a pen, and ten quiet minutes","same desk. i''m just not bracing anymore"]'::jsonb, '["the desk used to be where bad news happened","now it''s just a surface with a notebook on it","same desk, calmer person"]'::jsonb, 'the desk didn''t change. i did.', true, '2026-08-18T12:06:31.905Z', 1787054791905, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p32.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p32-w.jpg', '[]'::jsonb, 'smgen-1786161678991-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-desk-is-set-before-i-sit', 29, 'the desk is set before i sit', '["the desk is set before i sit down","lamp on, notebook open, pen already lying across the page","i do that the night before, so the version of me who shows up in the morning has nothing left to decide","she just sits down and the numbers are the only thing waiting"]'::jsonb, '["the lamp is on, the notebook is open, the pen is already there","i set it up the night before so morning me has nothing to decide","i sit down and the only thing left is the numbers"]'::jsonb, 'setting the desk the night before did more for me than any budget app', true, '2026-08-17T00:07:48.629Z', 1786925268629, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p31.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p31-w.jpg', '[]'::jsonb, 'smgen-1786074783145-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-light-tells-me-its-time', 30, 'the light tells me it''s time', '["the light tells me it''s time","when the sun reaches this side of the table, i sit down and open the notebook","one cup, one page, three numbers. what came in, what''s owed, what''s left","by the time the light moves off the table, i''m finished. the rest of the day doesn''t have to be about money"]'::jsonb, '["morning light on the table means the ten quiet minutes start","one cup, one page, three numbers — nothing more","by the time the light moves, i''m done thinking about money"]'::jsonb, 'the table gets ten quiet minutes, then i let it go', true, '2026-08-16T00:23:10.680Z', 1786839790680, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p30.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p30-w.jpg', '[]'::jsonb, 'smgen-1785987939981-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-give-the-week-a-page', 31, 'i give the week a page', '["i give the week a page","one page, one week, and i fill it in before i open anything else","bills go down the left side, the things i want go on the right, in the same handwriting","then the pen goes down, the planner stays open on the desk, and i go do something else"]'::jsonb, '["one page, one week, before anything else","bills on the left, wants on the right","then the pen goes down and i leave it alone"]'::jsonb, 'the whole ritual fits on one page', true, '2026-08-15T00:17:09.592Z', 1786753029592, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p29.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p29-w.jpg', '[]'::jsonb, 'smgen-1785906502522-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-count-it-out-loud', 32, 'i count it out loud', '["i count it out loud.","the money comes out of the envelope and i count it slow, like it''s someone else''s.","saying the number out loud takes the flinch out of it. it''s just a number in a room.","then it goes back in the envelope and i don''t think about it again till next week."]'::jsonb, '["cash comes out of the envelope and gets counted slowly, on purpose","saying the number out loud takes the fear out of it","then it goes back in and i''m done thinking about it"]'::jsonb, 'the counting is the calm part, not the scary part', true, '2026-08-14T00:44:07.909Z', 1786668247909, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p28.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p28-w.jpg', '[]'::jsonb, 'smgen-1785819176380-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-planner-opens-first', 33, 'the planner opens first', '["the planner opens first","before i open anything else, i open this page and put the pen on it","one line for what''s already spoken for. one line for what''s actually mine","then the pen goes down, the planner closes, and money is handled until next week"]'::jsonb, '["before the app, before the balance, the page gets opened","one line for what''s already spoken for, one line for what''s mine","pen down, planner closed, the money is handled for the week"]'::jsonb, 'the page goes first, the app goes second', true, '2026-08-13T00:23:28.692Z', 1786580608692, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p27.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p27-w.jpg', '[]'::jsonb, 'smgen-1785732278249-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-mug-is-the-timer', 34, 'the mug is the timer', '["the mug is the timer.","i sit down while it''s still hot, open the notebook, and go through the numbers once — no second lap.","warm light, one page, whatever''s true today gets written down calmly.","when the cup is empty, i close it and the money part of my day is done."]'::jsonb, '["the ritual is bounded by the cup, not by a mood","one warm desk, one notebook, one pass at the numbers","when the coffee''s gone, the money part of the day is over"]'::jsonb, 'one pass at the numbers, no second lap', true, '2026-08-12T00:14:08.875Z', 1786493648875, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p26.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p26-w.jpg', '[]'::jsonb, 'smgen-1785698201780-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-date-the-page-first', 35, 'i date the page first', '["i date the page first.","before a single number goes down, i write the day at the top — that''s the whole start of it.","then the pen just moves. what came in, what went out, no opinion attached.","and when the notebook closes, it''s a record. not a worry i carry around all week."]'::jsonb, '["before any number goes down, i write the day''s date at the top of the page","then the pen just moves — what came in, what went out, nothing i have to feel about it","by the time i close the notebook, the money is a record instead of a worry"]'::jsonb, 'the page gets the date before it gets the numbers 🤍', true, '2026-08-11T00:05:37.321Z', 1786406737321, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p25.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p25-w.jpg', '[]'::jsonb, 'smgen-1785554513947-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-cup-buys-me-ten-minutes', 36, 'the cup buys me ten minutes', '["the cup buys me ten minutes.","i don''t start with the numbers. i start with the coffee, and the numbers get however long it stays warm.","pen, paper, the desk exactly like this. what came in, what''s leaving, nothing else.","empty cup, closed notebook. that''s the whole ritual, and it holds all week."]'::jsonb, '["the coffee is the timer — while it''s hot, the money gets looked at","one page, one pen, no apps open yet","when the cup is empty i''m done, and it stays done till next week"]'::jsonb, 'the coffee is the timer and honestly that''s the only rule', true, '2026-08-10T01:16:17.963Z', 1786324577963, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p24.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p24-w.jpg', '[]'::jsonb, 'smgen-1785396459774-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-pen-stays-on-the-page', 37, 'the pen stays on the page', '["the pen stays on the page.","one notebook, one pen, ten minutes at the table.","i write what came in, then what''s already spoken for, and nothing else.","then the pen goes down, the book closes, and i don''t think about it again until next week."]'::jsonb, '["one notebook, one pen, ten minutes","i write what came in, then what''s spoken for","the pen goes down and i''m done until next week"]'::jsonb, 'ten minutes with a pen and the week feels held', true, '2026-08-09T01:06:54.156Z', 1786237614156, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p23.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p23-w.jpg', '[]'::jsonb, 'smgen-1784767444753-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-page-hears-the-numbers-first', 38, 'the page hears the numbers first', '["the page hears the numbers first.","before the app, before the panic, i open the notebook and just write what''s real.","what came in, what''s going out, one honest line each.","then i close it, and the numbers stay on the page instead of in my chest."]'::jsonb, '["open the notebook, pen down, no app yet","write what came in, what''s leaving, nothing else","close it — the worry stays on the page"]'::jsonb, 'the notebook goes first, always', true, '2026-08-08T00:59:47.008Z', 1786150787008, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p22.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p22-w.jpg', '[]'::jsonb, 'smgen-1784689146960-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'payday-in-three-small-moves', 39, 'payday, in three small moves', '["payday, in three small moves.","first the bills, while the coffee''s still hot.","then the small amount that''s just for later.","then i close the notebook, and the rest of the day is mine."]'::jsonb, '["hand opening the notebook under the lamp","pen resting beside a warm coffee","closing the cover, desk left tidy"]'::jsonb, 'three moves and i''m done thinking about it', true, '2026-08-07T00:50:55.930Z', 1786063855930, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p21.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p21-w.jpg', '[]'::jsonb, 'smgen-1784684392525-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-became-a-clear-desk-person', 40, 'i became a clear-desk person', '["i became a clear-desk person","turns out the desk came first, the calm followed","now the money sits at one tidy table, not everywhere at once","nothing on it i haven''t already made peace with"]'::jsonb, '["clear desk, one notebook open","the calm of nothing owed a decision","money handled at this small table"]'::jsonb, 'the desk got quiet and so did the money', true, '2026-08-06T00:43:44.791Z', 1785977024791, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p20.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p20-w.jpg', '[]'::jsonb, 'smgen-1784667430006-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-do-money-at-tea-temperature', 41, 'i do money at tea temperature', '["i do money at tea temperature.","not braced, not rushed — warm, and a little slow.","the tea gives my hands something to do while i look at the number.","by the time the cup''s empty, the week is quietly handled."]'::jsonb, '["tea steeping beside an open notebook, unhurried","hands resting, the number looked at calmly","empty cup, week already handled"]'::jsonb, 'the ritual is half the reset', true, '2026-08-05T00:27:49.279Z', 1785889669279, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p19.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p19-w.jpg', '[]'::jsonb, 'smgen-1784659668675-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-sit-down-for-this-now', 42, 'i sit down for this now', '["i sit down for this now.","there was a version of me who avoided the desk, who let the numbers pile up in the dark.","this one pulls out the chair, turns on the lamp, and stays for ten quiet minutes.","nothing about the money changed first. i did. the calm followed me here."]'::jsonb, '["settling at the warm desk, no bracing","the notebook and lamp make it a place, not a task","closing the book, calm, moving on with the day"]'::jsonb, 'the desk taught me before the numbers did', true, '2026-08-04T00:18:17.947Z', 1785802697947, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p18.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p18-w.jpg', '[]'::jsonb, 'smgen-1784653356318-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'each-envelope-has-one-job', 43, 'each envelope has one job', '["each envelope has one job","i count it out by hand, slow, on a sunday","this one for the roof, this one for the week, this one for the small wants","when every envelope is full, i stop thinking about the money"]'::jsonb, '["hands counting cash into a labeled envelope","sorting the stack into separate envelopes","sealing the last one and setting it down"]'::jsonb, 'giving each part of it a place to sit', true, '2026-08-03T01:26:16.339Z', 1785720376339, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p17.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p17-w.jpg', '[]'::jsonb, 'smgen-1784643940101-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-write-the-numbers-by-hand', 44, 'i write the numbers by hand', '["i write the numbers by hand","not because a screen can''t hold them","but because my hand goes slow enough to actually see them","the page doesn''t autocomplete the panic. i just write, then close it"]'::jsonb, '["hand moving a pen across an open journal page","the same figures, copied slowly instead of scrolled past","pen resting on the closed notebook, done for the week"]'::jsonb, 'the slowest way to look at money is the calmest one', true, '2026-08-02T00:43:40.184Z', 1785631420184, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p16.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p16-w.jpg', '[]'::jsonb, 'smgen-1784640787668-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-do-the-numbers-at-first-light', 45, 'i do the numbers at first light', '["i do the numbers at first light.","before the day gets loud, i sit with the number for a minute.","not to fix anything — just to know where i am.","then i close it, and the morning is mine again."]'::jsonb, '["morning light on the table, hands settling in","the small morning look at the money","closing it before the day gets loud"]'::jsonb, 'the quietest part of my morning is the honest part', true, '2026-08-01T01:35:21.882Z', 1785548121882, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p15.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p15-w.jpg', '[]'::jsonb, 'smgen-1784599685786-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-budget-by-candlelight-now-seriously-it-changed-the', 46, 'i budget by candlelight now. seriously. it changed the whole relationship', '["I budget by candlelight now. Seriously. It changed the whole relationship.","The numbers didn''t change. The room did. Warm light, no overhead glare, nothing clinical about it.","Your body decides how hard a task feels long before your mind gets a vote. A soft room makes a soft task.","So ambience turned out to be the strategy. It sounded silly right up until it was the reason I sat down."]'::jsonb, '["the numbers didn''t change, the room did","your body decides how hard a task feels","ambience is a strategy"]'::jsonb, 'ambience is a strategy.', true, '2026-07-31T01:12:46.253Z', 1785460366253, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p07.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p07-w.jpg', '[]'::jsonb, 'sm-27', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'coffee-first-then-the-numbers', 47, 'coffee first, then the numbers', '["coffee first, then the numbers","i don''t open the app until the cup is poured and i''m actually sitting down","one quiet look while it''s still warm — nothing to fix, just to know","then i close it and finish the coffee, and the day starts on my terms"]'::jsonb, '["pour the coffee, sit down before opening anything","one calm look at the accounts while it''s still warm","close the app, finish the cup, start the day held"]'::jsonb, 'the morning money ritual that keeps me calm', true, '2026-07-30T01:02:36.372Z', 1785373356372, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p14.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p14-w.jpg', '[]'::jsonb, 'smgen-1784598070025-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'payday-order-of-operations-rent-then-the-savings-transfer', 48, 'payday order of operations: rent, then the savings transfer, then i close the app and go make lunch', '["My payday order of operations. Rent, then the savings transfer, then I close the app and go make lunch.","Rent first, because it isn''t a choice. Doing it first stops it from following me through the day.","Savings second, before the wanting starts. Not a grand gesture. Just before, rather than after.","Then I close the app and leave. No lingering, no scrolling through the history looking for a reason to feel bad.","Four minutes, and it buys me a week of not thinking about it. That''s the trade, and it''s a good one."]'::jsonb, '["rent first, because it isn''t a choice","savings second, before the wanting starts","then i close the app and leave","four minutes, one quiet week"]'::jsonb, 'the whole thing takes four minutes and buys me a week of not thinking about it', true, '2026-07-23T00:18:15.681Z', 1784765895681, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p13.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p13-w.jpg', '[]'::jsonb, 'smgen-1784579090242-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-started-keeping-receipts-in-one-small-dish-instead', 49, 'i started keeping receipts in one small dish instead of six pockets. i think that''s what growing up looked like', '["I started keeping receipts in one small dish instead of six pockets. I think that''s what growing up actually looked like.","Six pockets meant six places to dread. Every coat was a small unopened question.","One dish means one place to look. The dread has a location now, and it''s the size of a saucer.","One dish, one Sunday, and everything else got quieter. Nothing about it was dramatic."]'::jsonb, '["six pockets meant six places to dread","one dish means one place to look","one sunday, and everything else got quieter"]'::jsonb, 'one dish. one sunday. everything else got quieter', true, '2026-07-22T02:31:15.700Z', 1784687475700, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p12.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p12-w.jpg', '[]'::jsonb, 'smgen-1784572762791-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-used-to-think-being-good-with-money-meant', 50, 'i used to think being good with money meant knowing more. it meant flinching less', '["I used to think being good with money meant knowing more. It turned out to mean flinching less.","I kept collecting information I never used. Saved articles, downloaded apps, watched explainers at midnight.","The gap was never knowledge. It was the sitting down. I could explain things I refused to look at.","Ten minutes and a pen. That''s the whole thing. It was never as complicated as I needed it to be."]'::jsonb, '["i kept collecting information i never used","the gap was never knowledge","ten minutes and a pen. that''s the whole thing"]'::jsonb, 'the reset is ten minutes and a pen. that''s the whole thing', true, '2026-07-22T00:22:53.007Z', 1784679773007, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p11.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p11-w.jpg', '[]'::jsonb, 'smgen-1784561969035-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-money-moves-before-i-have-an-opinion-about', 51, 'the money moves before i have an opinion about it', '["The money moves before I have an opinion about it.","Opinions arrive late and loud. Usually somewhere around the second scroll of the evening.","So the order runs first, on purpose. Before the mood shows up with suggestions.","That way I don''t have to do the deciding. The sequence already did it, back when I was calm."]'::jsonb, '["opinions arrive late and loud","the order runs first, on purpose","so i don''t have to do the deciding"]'::jsonb, 'the order does the deciding so i don''t have to', true, '2026-07-21T20:31:54.276Z', 1784665914276, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p10.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p10-w.jpg', '[]'::jsonb, 'smgen-1784554175623-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'payday-has-an-order-and-i-dont-have-to', 52, 'payday has an order and i don''t have to decide anything on the day', '["Payday has an order, and I don''t have to decide anything on the day.","The deciding already happened, weeks ago, when I was calm and nothing was urgent.","Today I just follow it. Step, step, step, close the app, go make lunch.","No negotiating with a tired brain. That''s really what the order is protecting me from."]'::jsonb, '["the deciding happened weeks ago","today i just follow it","no negotiating with a tired brain"]'::jsonb, 'the deciding already happened. today i just follow it', true, '2026-07-21T17:54:13.597Z', 1784656453597, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p09.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p09-w.jpg', '[]'::jsonb, 'smgen-1784517607324-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-used-to-open-my-banking-app-braced-now', 53, 'i used to open my banking app braced. now i open it the way i open a drawer', '["I used to open my banking app braced. Now I open it the way I open a drawer.","The bracing was a habit, not a reaction. My shoulders did it before the screen even loaded.","A drawer is just a place where things are kept. You open it to find out what''s in there. That''s all.","Nothing changed except the flinch. And that turned out to be the entire change."]'::jsonb, '["bracing was a habit, not a reaction","a drawer is just a place where things are kept","nothing changed except the flinch"]'::jsonb, 'nothing changed except the flinch — that was the whole change', true, '2026-07-21T16:11:54.279Z', 1784650314279, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p08.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p08-w.jpg', '[]'::jsonb, 'smgen-1784509880141-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'sunday-tea-notebook-numbers-the-week-can-come-now', 54, 'sunday. tea, notebook, numbers. the week can come now', '["Sunday. Tea, notebook, numbers. The week can come now.","Everything is written down and nothing is hiding. Whatever''s true is already on the page.","Which means I don''t have to hold any of it. The holding is what used to exhaust me.","Ready is quiet. It doesn''t feel like triumph. It feels like a room after you''ve tidied it."]'::jsonb, '["everything is written down and nothing is hiding","i don''t have to hold any of it","ready is quiet"]'::jsonb, 'ready is quiet.', true, '2026-07-21T13:59:06.583Z', 1784642346583, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04-w.jpg', '[]'::jsonb, 'sm-30', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'money-got-lighter-the-day-it-got-a-routine', 55, 'money got lighter the day it got a routine', '["Money got lighter the day it got a routine.","Before that I carried it constantly and never once set it down. It was always half-open in the background.","A routine gives it somewhere to live. A time, a place, a page. Somewhere that isn''t my head.","Carried daily, it weighs less. Held all at once, it weighs everything."]'::jsonb, '["before, i carried it constantly and never set it down","a routine gives it somewhere to live","carried daily, weighs less"]'::jsonb, 'carried daily, weighs less.', true, '2026-07-21T12:16:00.706Z', 1784636160706, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03-w.jpg', '[]'::jsonb, 'sm-29', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-goal-was-never-more-the-goal-was-calm', 56, 'the goal was never more. the goal was calm arithmetic', '["The goal was never more. The goal was calm arithmetic.","More without order is still loud. The noise doesn''t leave on its own just because the number moved.","What I actually wanted was numbers I could look at plainly, on an ordinary Tuesday, without bracing.","Arithmetic that doesn''t shout. That was the thing I was chasing the entire time."]'::jsonb, '["more without order is still loud","i wanted numbers i could look at plainly","arithmetic that doesn''t shout"]'::jsonb, 'numbers that don''t shout.', true, '2026-07-21T01:42:08.422Z', 1784598128422, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05-w.jpg', '[]'::jsonb, 'sm-28', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'quiet-money-isnt-rich-money-its-known-money', 57, 'quiet money isn''t rich money. it''s known money', '["Quiet money isn''t rich money. It''s known money.","Guessing is what makes it loud. The not-knowing fills the room with worst cases.","And knowing is available at any size. It doesn''t wait for a better year to become possible.","Known beats guessed. That''s the whole difference between the page I dreaded and the page I just read."]'::jsonb, '["guessing is what makes it loud","knowing is available at any size","known beats guessed"]'::jsonb, 'known beats guessed.', true, '2026-07-20T19:59:43.150Z', 1784577583150, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01-w.jpg', '[]'::jsonb, 'sm-26', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-version-of-me-that-looks-at-the-number', 58, 'the version of me that looks at the number before it looks at me', '["The version of me that looks at the number before the number looks at me.","She goes first, on her own schedule, in her own kitchen, with tea. Nothing gets to arrive at her.","Being surprised was always what actually hurt. Not the amount. The ambush.","First move wins. That''s most of it, honestly."]'::jsonb, '["she goes first, on her own schedule","being surprised is what actually hurt","first move wins"]'::jsonb, 'first move wins.', true, '2026-07-20T17:49:05.563Z', 1784569745563, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02-w.jpg', '[]'::jsonb, 'sm-25', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'you-dont-need-a-better-spreadsheet-you-need-a', 59, 'you don''t need a better spreadsheet. you need a gentler appointment with the one you have', '["You don''t need a better spreadsheet. You need a gentler appointment with the one you already have.","The new app is usually just avoidance in a nicer font. Setup feels like progress, and setup is free.","You never actually abandoned the tool. You abandoned the sitting down. That''s the part that got hard.","It was never the tool. Once the sitting down got small and kind, the spreadsheet I already had held fine."]'::jsonb, '["the new app is just avoidance in a nicer font","you never abandoned the tool, you abandoned the sitting-down","it''s not the tool"]'::jsonb, 'it''s not the tool.', true, '2026-07-20T15:14:19.750Z', 1784560459750, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06-w.jpg', '[]'::jsonb, 'sm-24', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-romanticize-the-money-reset-the-way-people-romanticize', 60, 'i romanticize the money reset the way people romanticize sunday cleaning. same relief', '["I romanticize the money reset the way people romanticize Sunday cleaning. It''s the same relief.","It''s the same instinct, really. Put the mess somewhere you can see it, and it stops feeling infinite.","The relief comes from order, not from having more. That''s true of a countertop and it''s true of a page.","Clean numbers, clean counters. Both of them just let the week start without a backlog."]'::jsonb, '["same instinct: put the mess where you can see it","the relief comes from order, not from more","clean numbers, clean counters"]'::jsonb, 'clean numbers, clean counters.', true, '2026-07-20T12:13:20.611Z', 1784549600611, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p07.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p07-w.jpg', '[]'::jsonb, 'sm-23', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-bills-paid-themselves-on-time-because-past-you', 61, 'the bills paid themselves on time because past-you set the table', '["The bills paid themselves on time, because past-you set the table.","She made the decisions on a calm afternoon, when nothing was urgent and nothing was tempting.","So today required nothing from you at all. No remembering, no scrambling, no apology emails.","Nothing about today was work. It was built by someone I already was."]'::jsonb, '["she made the decisions on a calm afternoon","today required nothing from you","thank her later"]'::jsonb, 'past-me set the table.', true, '2026-07-20T02:54:41.915Z', 1784516081915, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03-w.jpg', '[]'::jsonb, 'sm-22', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'small-money-rituals-are-how-you-become-someone-money', 62, 'small money rituals are how you become someone money feels safe around', '["Small money rituals are how you become someone money feels safe around.","You slowly learn that you can look at it without falling apart. That''s the whole lesson.","The trust isn''t really in the money. It''s in yourself, in how you handle what you find.","And it builds one quiet Sunday at a time. Nobody arrives there in a weekend."]'::jsonb, '["you learn you can look without falling apart","the trust is really trust in yourself","it builds one quiet sunday at a time"]'::jsonb, 'trust builds both ways.', true, '2026-07-20T00:19:04.806Z', 1784506744806, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04-w.jpg', '[]'::jsonb, 'sm-21', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-notebook-doesnt-judge-thats-why-it-works', 63, 'the notebook doesn''t judge. that''s why it works', '["The notebook doesn''t judge. That''s exactly why it works.","No notifications. No tone. No little opinion about the week I just had.","It just holds what I tell it, in my own handwriting, at my own pace.","Paper is patient. It''ll wait for me, and it never once made me feel behind."]'::jsonb, '["no notifications, no tone, no opinion","it just holds what i tell it","paper is patient"]'::jsonb, 'paper is patient.', true, '2026-07-19T19:33:55.706Z', 1784489635706, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00-w.jpg', '[]'::jsonb, 'sm-20', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-stopped-checking-my-account-at-midnight-we-talk', 64, 'i stopped checking my account at midnight. we talk during business hours now', '["I stopped checking my account at midnight. We talk during business hours now.","Nothing I find at midnight can actually be acted on. It''s pure looking with nowhere to put it.","And a tired brain reads every number worse than it is. Midnight makes fine things look dire.","So I keep boundaries, even with my own banking app. It can have my attention. It just can''t have my night."]'::jsonb, '["nothing at midnight can be acted on","the tired brain reads every number worse","boundaries, even with my own bank app"]'::jsonb, 'boundaries with my own bank app.', true, '2026-07-19T17:18:50.333Z', 1784481530333, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06-w.jpg', '[]'::jsonb, 'sm-19', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'money-anxiety-shrinks-when-its-scheduled-it-grows-when', 65, 'money anxiety shrinks when it''s scheduled. it grows when it''s ambient', '["Money anxiety shrinks when it''s scheduled. It grows when it''s ambient.","Ambient worry has no end point. It follows you into the shower, into bed, into perfectly good afternoons.","A scheduled worry has a door out. You go in, you look, you leave. It has a shape.","So I gave it an appointment. Not to make it bigger — to give it edges it didn''t have before."]'::jsonb, '["ambient worry has no end point","a scheduled worry has a door out","give it an appointment"]'::jsonb, 'scheduled, not ambient.', true, '2026-07-19T15:09:23.267Z', 1784473763267, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05-w.jpg', '[]'::jsonb, 'sm-18', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-unsubscribed-from-every-store-email-and-started-hearing', 66, 'i unsubscribed from every store email and started hearing my own opinions again', '["I unsubscribed from every store email, and I started hearing my own opinions again.","So much of my wanting had been scheduled by someone else. A sale arrived, and a feeling followed.","Quiet inbox, quieter wants. It took about two weeks for the noise to drain out.","The things I still want after that are actually mine. That''s a much shorter list, and a much better one."]'::jsonb, '["most of my wanting was scheduled by someone else","quiet inbox, quieter wants","the things i still want are actually mine"]'::jsonb, 'quiet inbox, quiet wants.', true, '2026-07-19T12:08:10.450Z', 1784462890450, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02-w.jpg', '[]'::jsonb, 'sm-17', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'ten-minutes-on-sunday-saves-me-five-small-panics', 67, 'ten minutes on sunday saves me five small panics by thursday', '["Ten minutes on Sunday saves me about five small panics by Thursday.","The panics were never about the money itself. They were about not knowing, at a bad moment.","One look on Sunday answers all of them at once. Thursday-me just remembers instead of guessing.","It''s cheap insurance. Ten quiet minutes, traded for a week of not startling myself."]'::jsonb, '["the panics were always about not knowing","one look answers all of them at once","cheap insurance"]'::jsonb, 'cheap insurance.', true, '2026-07-19T02:27:14.679Z', 1784428034679, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04-w.jpg', '[]'::jsonb, 'sm-16', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'my-bank-balance-is-information-not-a-grade', 68, 'my bank balance is information, not a grade', '["My bank balance is information. It is not a grade.","A number can''t have an opinion about me. It doesn''t know how my year went or what it cost.","I gave it the meaning it had. Which means I''m allowed to take that meaning back.","Data, not judgment. Once it''s just data, I can actually look at it without bracing."]'::jsonb, '["a number can''t have an opinion about you","i gave it the meaning, so i can take it back","data, not judgment"]'::jsonb, 'data, not judgment.', true, '2026-07-19T00:19:21.312Z', 1784420361312, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06-w.jpg', '[]'::jsonb, 'sm-15', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'its-payday-and-you-move-the-money-in-the', 69, 'it''s payday, and you move the money in the same order as always. no drama, just choreography', '["It''s payday, and you move the money in the same order as always. No drama. Just choreography.","The order got decided on a calm day, weeks ago, by someone who wasn''t tired or tempted.","So payday isn''t a decision anymore. It''s a sequence. You just follow the steps you already agreed to.","Rehearsed calm beats fresh willpower every single time. Willpower runs out. A sequence doesn''t."]'::jsonb, '["the order was decided on a calm day","payday isn''t a decision anymore, it''s a sequence","rehearsed calm beats fresh willpower"]'::jsonb, 'rehearsed calm.', true, '2026-07-18T19:09:41.758Z', 1784401781758, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03-w.jpg', '[]'::jsonb, 'sm-14', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-calmest-thing-i-own-is-a-notebook-that', 70, 'the calmest thing i own is a notebook that knows where my money goes', '["The calmest thing I own is a notebook that knows where my money goes.","It remembers so I don''t have to. That''s its entire job, and it never forgets.","Nothing lives in my head rent free anymore. It''s all on a page I can go find.","An outsourced memory is a quiet one. The relief isn''t in the numbers. It''s in not carrying them."]'::jsonb, '["it remembers so i don''t have to","nothing lives in my head rent free","an outsourced memory is a quiet one"]'::jsonb, 'it remembers so i can rest.', true, '2026-07-18T17:02:57.264Z', 1784394177264, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00-w.jpg', '[]'::jsonb, 'sm-13', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'wanting-things-is-fine-the-ritual-just-asks-me', 71, 'wanting things is fine. the ritual just asks me to want them on purpose', '["Wanting things is fine. The ritual just asks me to want them on purpose.","It never says no. There''s no forbidden list, no punishment for enjoying something.","It just asks me to say the want out loud first. Half of them don''t survive being said out loud.","On purpose is the whole trick. The ones that do survive, I get to have without a single ounce of guilt."]'::jsonb, '["the ritual doesn''t say no","it just asks me to say it out loud first","on purpose is the whole trick"]'::jsonb, 'on purpose is the whole trick.', true, '2026-07-18T14:26:16.183Z', 1784384776183, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01-w.jpg', '[]'::jsonb, 'sm-12', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-write-down-what-i-spent-like-id-tell', 72, 'i write down what i spent like i''d tell a friend — no verdict, just the truth', '["I write down what I spent the way I''d tell a friend. No verdict, just the truth.","A friend gets the facts without the lecture. That''s the tone I aim for on the page.","Because shame makes you stop writing things down. And a half-written page tells you nothing.","Honest pages only happen in kind rooms. The kindness isn''t soft. It''s what keeps the record accurate."]'::jsonb, '["a friend gets the facts without the lecture","shame makes you stop writing things down","honest pages only happen in kind rooms"]'::jsonb, 'honesty without a lecture.', true, '2026-07-18T12:16:35.377Z', 1784376995377, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05-w.jpg', '[]'::jsonb, 'sm-11', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'a-money-ritual-isnt-about-the-math-its-about', 73, 'a money ritual isn''t about the math. it''s about not flinching', '["A money ritual isn''t really about the math. It''s about not flinching.","The math was never the hard part. Most of us can add. We just can''t look.","Repetition is what takes the charge out of it. The tenth time you sit down, it''s mundane.","The flinch turned out to be optional. It was a habit like any other, and mine softened once the ritual got boring."]'::jsonb, '["the math was never the hard part","repetition is what takes the charge out","the flinch is optional"]'::jsonb, 'the flinch is optional.', true, '2026-07-18T03:10:08.308Z', 1784344208308, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04-w.jpg', '[]'::jsonb, 'sm-10', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-version-of-me-that-knows-whats-coming-out', 74, 'the version of me that knows what''s coming out this week sleeps differently', '["The version of me that knows what''s coming out this week sleeps differently.","No surprises means no three a.m. math. That''s the hour where everything feels worse than it is.","The knowing is the whole comfort. My brain stops running the numbers because it already has them.","She isn''t ahead of anything. She''s just informed. That was enough to change the nights."]'::jsonb, '["no surprises means no 3am math","the knowing is the whole comfort","she isn''t ahead, she''s just informed"]'::jsonb, 'no surprises, no 3am math.', true, '2026-07-18T00:17:09.453Z', 1784333829453, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02-w.jpg', '[]'::jsonb, 'sm-09', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'avoidance-is-the-most-expensive-habit-i-ever-had', 75, 'avoidance is the most expensive habit i ever had', '["Avoidance is the most expensive habit I ever had.","Not looking never made anything smaller. It just meant I found out later, with less room to respond.","And it moved the worry into every hour instead of one. Ambient dread is a tax you pay all week.","Looking costs nothing. It''s uncomfortable for about ninety seconds, and then it''s over."]'::jsonb, '["not looking never made it smaller","it just moved the worry into every hour","looking costs nothing"]'::jsonb, 'looking costs nothing.', true, '2026-07-17T20:22:21.557Z', 1784319741557, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p06-w.jpg', '[]'::jsonb, 'sm-08', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'its-sunday-evening-the-notebook-is-open-and-money', 76, 'it''s sunday evening, the notebook is open, and money is just a list of small decisions again', '["It''s Sunday evening. The notebook is open. And money is just a list of small decisions again.","Nothing on this page is a verdict. It''s not scoring me. It''s a page.","Each line is one small choice, sitting on its own, where I can actually see it.","It was never a monster. It was a pile. It went quiet the moment I sorted it."]'::jsonb, '["nothing here is a verdict","each line is just one small choice","it was never a monster, only a pile"]'::jsonb, 'it was never a monster.', true, '2026-07-17T17:50:15.099Z', 1784310615099, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00-w.jpg', '[]'::jsonb, 'sm-07', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'i-dont-budget-harder-anymore-i-budget-quieter', 77, 'i don''t budget harder anymore. i budget quieter', '["I don''t budget harder anymore. I budget quieter.","Harder meant elaborate rules I could never keep for more than two weeks. Then the shame, then the quitting.","Quieter just means one small honest look, on a regular day, without a whole personality change attached.","Volume down, clarity up. It turns out I didn''t need more discipline. I needed less noise."]'::jsonb, '["harder meant rules i couldn''t keep","quieter means one small honest look","volume down, clarity up"]'::jsonb, 'volume down, clarity up.', true, '2026-07-17T15:11:51.879Z', 1784301111879, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p05-w.jpg', '[]'::jsonb, 'sm-06', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'money-stopped-being-scary-when-it-became-a-ten', 78, 'money stopped being scary when it became a ten minute tea date every sunday', '["Money stopped being scary when it became a ten minute tea date every Sunday.","It''s an appointment now, not an ambush. It happens when I decide, not when panic decides.","And I make it pleasant on purpose. Tea, good light, no phone. The setting does half the work.","I stopped dreading it once it had a time on it. The dread was living in the not-knowing-when."]'::jsonb, '["an appointment, not an ambush","i make it pleasant on purpose","you can''t dread something you''ve already scheduled"]'::jsonb, 'an appointment, not an ambush.', true, '2026-07-17T12:11:58.710Z', 1784290318710, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p04-w.jpg', '[]'::jsonb, 'sm-05', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'payday-order-bills-savings-then-im-allowed-to-want', 79, 'payday order: bills, savings, then i''m allowed to want things', '["My payday order. Bills, then savings, and then I''m allowed to want things.","Bills first, because they were never really a choice. Doing them first stops them from following me around.","Savings second, before the wanting starts. Not a big gesture. Just before, rather than after.","And then whatever is left is genuinely mine to enjoy. No guilt attached, because the order already answered for me."]'::jsonb, '["bills first, because they aren''t a choice","savings second, before the wanting starts","then whatever''s left is genuinely mine"]'::jsonb, 'same order every time.', true, '2026-07-17T03:19:35.968Z', 1784258375968, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p03-w.jpg', '[]'::jsonb, 'sm-04', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-version-of-me-that-opens-the-banking-app', 80, 'the version of me that opens the banking app calmly is a different person', '["The version of me that opens the banking app calmly is a different person.","Same numbers. Different nervous system. Nothing on the screen changed at all.","She isn''t braver than I was. She just already knows roughly what she''s about to see.","The calm came from the routine, not from the balance. It took me two years to notice that."]'::jsonb, '["same numbers, different nervous system","she isn''t braver, she''s just informed","calm came from the routine, not the balance"]'::jsonb, 'same numbers, different nervous system.', true, '2026-07-17T01:35:34.114Z', 1784252134114, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p02-w.jpg', '[]'::jsonb, 'sm-03', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'checking-your-balance-with-one-eye-closed-is-a', 81, 'checking your balance with one eye closed is a symptom, not a joke', '["Checking your balance with one eye closed is a symptom. Not a joke.","The flinch is telling you something. Not about the number, about the feeling you''ve attached to it.","The number was never really the scary part. Not knowing was. Uncertainty is what your body reacts to.","So I look on purpose, at a time I chose. It''s gentler than being surprised by it at midnight."]'::jsonb, '["the flinch is information about the feeling","the number was never the scary part","looking on purpose is gentler than being surprised"]'::jsonb, 'gentler ways exist.', true, '2026-07-16T23:46:12.527Z', 1784245572527, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p01-w.jpg', '[]'::jsonb, 'sm-02', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-sunday-money-reset-ten-quiet-minutes-then-i', 82, 'the sunday money reset: ten quiet minutes, then i stop thinking about it all week', '["The Sunday money reset. Ten quiet minutes, and then I stop thinking about it all week.","Same chair, same tea, same ten minutes. The sameness is the point. There''s nothing to decide about the ritual itself.","I look at what''s coming, not at what''s wrong. It''s a list of small decisions, not a report card.","Then I close the notebook. And the rest of the week stays quiet, because the looking already happened."]'::jsonb, '["same chair, same tea, same ten minutes","i look at what''s coming, not what''s wrong","then i close the notebook and the week is quiet"]'::jsonb, 'sunday, tea, notebook. done.', true, '2026-07-16T21:39:17.901Z', 1784237957901, 'ritual', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p00-w.jpg', '[]'::jsonb, 'sm-01', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('softmoneyjournal', 'the-envelope-i-stopped-using', 3, 'the envelope i stopped using', '["i pay the envelopes in order.","the order is decided before the cash ever leaves the bank, the same sequence every payday.","bills envelope first, then the one i never touch, then groceries — same order every payday.","whatever is left in my hands after that is allowed to be fun money."]'::jsonb, '["the order is decided before the cash ever leaves the bank","each envelope gets filled in the same order every time","whatever is left over is mine to spend without guilt"]'::jsonb, 'same order every payday and the guilt never shows up', true, '2026-09-12T00:39:56.464Z', 1789173596464, 'payday-order', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p57.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/softmoneyjournal/plates/p57-w.jpg', '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('ledgerlight', 'the-column-i-file-on-fridays', 18, 'the column i file on fridays', '[]'::jsonb, '[]'::jsonb, 'the column i file on fridays', true, '2026-09-12T07:15:00+00:00', 1789197300000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('ledgerlight', 'two-figures-and-a-ruled-line', 17, 'two figures and a ruled line', '[]'::jsonb, '[]'::jsonb, 'two figures and a ruled line', true, '2026-09-05T07:15:00+00:00', 1788592500000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('ledgerlight', 'the-drawer-with-the-receipts', 16, 'the drawer with the receipts', '[]'::jsonb, '[]'::jsonb, 'the drawer with the receipts', true, '2026-08-29T07:15:00+00:00', 1787987700000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('themondaycolumn', 'monday-is-for-the-small-sums', 31, 'monday is for the small sums', '[]'::jsonb, '[]'::jsonb, 'monday is for the small sums', true, '2026-09-15T06:40:00+00:00', 1789454400000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('themondaycolumn', 'what-the-standing-order-does', 30, 'what the standing order does', '[]'::jsonb, '[]'::jsonb, 'what the standing order does', true, '2026-09-08T06:40:00+00:00', 1788849600000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz);
